#include "audio.hpp"
#include <filesystem>
#include <random>
#include <iostream>
#include <memory>
#include <thread>

namespace fs = std::filesystem;

void AudioManager::caricaMusiche(const std::string& cartella) {
    playlist.clear();

    if (!fs::exists(cartella) || !fs::is_directory(cartella)) {
        std::cerr << "Cartella musica non trovata: " << cartella << std::endl;
        return;
    }

    for (const auto& entry : fs::directory_iterator(cartella)) {
        if (!entry.is_regular_file()) continue;

        auto est = entry.path().extension().string();
        if (est == ".mp3" || est == ".ogg" || est == ".wav") {
            playlist.push_back(entry.path().string());
        }
    }

    if (playlist.empty()) {
        std::cerr << "Nessun file audio trovato in: " << cartella << std::endl;
    }
}

bool AudioManager::avviaMusica(const std::string& file){
    if (!musica.openFromFile(file)) {
        std::cerr << "Errore caricando musica: " << file << std::endl;
        return false;
    }
    musica.play();
    return true;
}

void AudioManager::avviaMusicaCasuale() {
    if (playlist.empty()) return;

    static std::mt19937 rng{ std::random_device{}() };
    std::uniform_int_distribution<size_t> dist(0, playlist.size() - 1);

    const std::string& file = playlist[dist(rng)];
    avviaMusica(file);
}

void AudioManager::aggiornaMusica() {
    if (musica.getStatus() == sf::Music::Status::Stopped) {
        avviaMusicaCasuale();
    }
}

void AudioManager::fermaMusica() {
    musica.stop();
}

void AudioManager::setVolumeMusica(float volume) {
    musica.setVolume(volume);
}

void AudioManager::setVolumeSuoni(float volume) {
    for (auto& [nome, sound] : sounds) {
        sound->setVolume(volume);
    }
}

void AudioManager::caricaSuono(const std::string& nome, const std::string& file) {
    auto buffer = std::make_shared<sf::SoundBuffer>();
    if (!buffer->loadFromFile("sounds/sfx/" + file + ".wav")) {
        std::cerr << "Errore caricando suono: " << file << std::endl;
        return;
    }
    buffers[nome] = buffer;

    // Creazione dello sf::Sound direttamente con il buffer
    auto sound = std::make_shared<sf::Sound>(*buffer);
    sounds[nome] = sound;
}

void AudioManager::suona(const std::string& nome) {
    auto it = sounds.find(nome);
    if (it != sounds.end()) {
        it->second->play();
    }
}

#include "audio.hpp"
#include <filesystem>
#include <random>
#include <iostream>
#include <memory>
#include <thread>
#include <cctype>

namespace fs = std::filesystem;

namespace {
unsigned int seed_non_bloccante() {
    const auto now = static_cast<unsigned long long>(
        std::chrono::steady_clock::now().time_since_epoch().count());
    const auto tid = static_cast<unsigned long long>(std::hash<std::thread::id>{}(std::this_thread::get_id()));
    return static_cast<unsigned int>(now ^ (tid + 0x9e3779b9ULL + (now << 6) + (now >> 2)));
}

std::string estensione_minuscola(std::string ext) {
    for (char& ch : ext) {
        ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
    }
    return ext;
}
}

void AudioManager::caricaMusiche(const std::string& cartella) {
    playlist.clear();
    rng.seed(seed_non_bloccante());

    if (!fs::exists(cartella) || !fs::is_directory(cartella)) {
        std::cerr << "Cartella musica non trovata: " << cartella << std::endl;
        return;
    }

    for (const auto& entry : fs::directory_iterator(cartella)) {
        if (!entry.is_regular_file()) continue;

        auto est = estensione_minuscola(entry.path().extension().string());
        if (est == ".mp3" || est == ".ogg" || est == ".wav") {
            playlist.push_back(entry.path().string());
        }
    }

    if (playlist.empty()) {
        std::cerr << "Nessun file audio trovato in: " << cartella << std::endl;
    }
}

bool AudioManager::avviaMusica(const std::string& file){
    if (!musica.openFromFile(file)) {
        std::cerr << "Errore caricando musica: " << file << std::endl;
        return false;
    }

    musica.play();
    return musica.getStatus() != sf::Music::Status::Stopped;
}

void AudioManager::avviaMusicaCasuale() {
    if (playlist.empty()) return;

    std::uniform_int_distribution<size_t> dist(0, playlist.size() - 1);
    const std::string& file = playlist[dist(rng)];

    if (!avviaMusica(file)) {
        // Evita loop stretto se device/decoder non parte: ritenta più avanti.
        prossimoTentativo = std::chrono::steady_clock::now() + std::chrono::milliseconds(500);
    }
}

void AudioManager::aggiornaMusica() {
    if (playlist.empty()) return;
    if (musica.getStatus() != sf::Music::Status::Stopped) return;
    if (std::chrono::steady_clock::now() < prossimoTentativo) return;

    avviaMusicaCasuale();
}

void AudioManager::fermaMusica() {
    musica.stop();
}

void AudioManager::setVolumeMusica(float volume) {
    musica.setVolume(volume);
}

void AudioManager::setVolumeSuoni(float volume) {
    for (auto& [nome, sound] : sounds) {
        sound->setVolume(volume);
    }
}

void AudioManager::caricaSuono(const std::string& nome, const std::string& file) {
    auto buffer = std::make_shared<sf::SoundBuffer>();
    if (!buffer->loadFromFile("sounds/sfx/" + file + ".wav")) {
        std::cerr << "Errore caricando suono: " << file << std::endl;
        return;
    }
    buffers[nome] = buffer;

    // Creazione dello sf::Sound direttamente con il buffer
    auto sound = std::make_shared<sf::Sound>(*buffer);
    sounds[nome] = sound;
}

void AudioManager::suona(const std::string& nome) {
    auto it = sounds.find(nome);
    if (it != sounds.end()) {
        it->second->play();
    }
}

#pragma once

#include <SFML/Audio.hpp>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>

class AudioManager {
public:
    void caricaMusiche(const std::string& cartella);
    bool avviaMusica(const std::string& file);
    void avviaMusicaCasuale();
    void aggiornaMusica();   
    void fermaMusica();
    void setVolumeMusica(float volume);

    void caricaSuono(const std::string& nome, const std::string& file);
    void suona(const std::string& nome);
    void setVolumeSuoni(float volume);

private:
    sf::Music musica;
    std::vector<std::string> playlist;

    std::unordered_map<std::string, std::shared_ptr<sf::SoundBuffer>> buffers;
    std::unordered_map<std::string, std::shared_ptr<sf::Sound>> sounds;
};

#pragma once

#include <SFML/Audio.hpp>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <random>
#include <chrono>

class AudioManager {
public:
    void caricaMusiche(const std::string& cartella);
    bool avviaMusica(const std::string& file);
    void avviaMusicaCasuale();
    void aggiornaMusica();   
    void fermaMusica();
    void setVolumeMusica(float volume);

    void caricaSuono(const std::string& nome, const std::string& file);
    void suona(const std::string& nome);
    void setVolumeSuoni(float volume);

private:
    sf::Music musica;
    std::vector<std::string> playlist;

    std::unordered_map<std::string, std::shared_ptr<sf::SoundBuffer>> buffers;
    std::unordered_map<std::string, std::shared_ptr<sf::Sound>> sounds;

    std::mt19937 rng{std::mt19937::default_seed};
    std::chrono::steady_clock::time_point prossimoTentativo{std::chrono::steady_clock::now()};
};
